-- Adds full course cards and workbook hole-by-hole scores to the seven 2026 display-only historic fixtures.
-- Historic fixture totals, score differentials and Order of Merit data are not recalculated or changed.
begin;
do $$
declare v_setup uuid; v_fixture uuid; begin
  select f.course_setup_id, f.id into v_setup, v_fixture from public.fixtures f where f.is_historical = true and f.fixture_date = date '2026-03-29' and f.name = 'Stockwood Park' limit 1;
  if v_fixture is null or v_setup is null then raise exception 'Historic fixture missing: 2026-03-29 Stockwood Park'; end if;
  update public.course_setups set tee_name = 'Yellow (historic)', par = 69 where id = v_setup;
  delete from public.hole_scores h using public.fixture_entries e where h.fixture_entry_id = e.id and e.fixture_id = v_fixture;
  update public.fixture_entries set score_differential = null where fixture_id = v_fixture;
end $$;
