commit;
select count(*) as historical_hole_scores from public.hole_scores h join public.fixture_entries e on e.id=h.fixture_entry_id join public.fixtures f on f.id=e.fixture_id where f.is_historical = true and f.fixture_date between date '2026-03-29' and date '2026-08-02';
